/* Service worker (Phase 10 PWA) — generated by App\Http\Controllers\PwaController */
const CFG = @json($config, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
@verbatim
const APP = 'mb-' + CFG.app + '-';
const PAGES = APP + 'pages-' + CFG.version;
const ASSETS = APP + 'assets-' + CFG.version;
const CORE = APP + 'core-' + CFG.version;     // precached layout files — never trimmed
const CDN = ['cdn.jsdelivr.net', 'cdnjs.cloudflare.com', 'fonts.googleapis.com', 'fonts.gstatic.com'];
const STATIC_DIRS = ['/css/', '/js/', '/images/', '/storage/', '/build/', '/vendor/'];

self.addEventListener('install', (e) => {
    self.skipWaiting();
    e.waitUntil(precache());
});

self.addEventListener('activate', (e) => {
    e.waitUntil((async () => {
        // remove only THIS app's caches of older versions (other stores share the origin)
        const keys = await caches.keys();
        await Promise.all(keys.filter((k) => k.startsWith(APP) && ![PAGES, ASSETS, CORE].includes(k)).map((k) => caches.delete(k)));
        await self.clients.claim();
    })());
});

async function precache() {
    const c = await caches.open(CORE);
    await Promise.allSettled((CFG.precache || []).map(async (u) => {
        const cross = new URL(u, self.location.href).origin !== self.location.origin;
        const res = await fetch(new Request(u, cross ? { mode: 'no-cors' } : {}));
        if (res && (res.ok || res.type === 'opaque')) await c.put(u, res);
    }));
    if (CFG.start) {
        try {
            const res = await fetch(CFG.start, { credentials: 'include' });
            if (res.ok && !res.redirected) await (await caches.open(PAGES)).put(pageKey(new URL(CFG.start)), res);
        } catch (err) { /* offline during install */ }
    }
}

function inScope(url) {
    return url.origin === self.location.origin && (CFG.scope === '/' || url.pathname === CFG.scope || url.pathname.startsWith(CFG.scope.replace(/\/$/, '') + '/'));
}

function isAsset(req, url) {
    if (url.origin !== self.location.origin) return CDN.includes(url.hostname);
    if (['style', 'script', 'font', 'image'].includes(req.destination)) return true;
    return STATIC_DIRS.some((d) => url.pathname.includes(d));
}

/** cache key of a page: without the ?source=pwa marker */
function pageKey(url) {
    const u = new URL(url.href);
    u.searchParams.delete('source');
    u.hash = '';
    return u.href;
}

async function trim(name, max) {
    const c = await caches.open(name);
    const keys = await c.keys();
    for (let i = 0; i < keys.length - max; i++) await c.delete(keys[i]);
}

/** Pages: network first (always fresh when online), last good copy when offline. */
async function page(req, url, cacheIt) {
    try {
        const res = await fetch(req);
        // X-PWA-Private: page shows a logged-in customer → not kept on the device
        if (cacheIt && res.ok && !res.redirected && res.type === 'basic' && !res.headers.get('x-pwa-private')
            && (res.headers.get('content-type') || '').includes('text/html')) {
            const c = await caches.open(PAGES);
            await c.put(pageKey(url), res.clone());
            trim(PAGES, CFG.maxPages || 40);
        }
        return res;
    } catch (err) {
        const c = await caches.open(PAGES);
        return (await c.match(pageKey(url))) || (await fallback(c)) || offlinePage();
    }
}

/** Static files: served from the cache at once, refreshed in the background. */
async function asset(e, req) {
    const c = await caches.open(ASSETS);
    const hit = (await c.match(req, { ignoreVary: true })) || (await (await caches.open(CORE)).match(req, { ignoreVary: true }));
    const net = fetch(req).then((res) => {
        if (res && (res.ok || res.type === 'opaque')) {
            c.put(req, res.clone()).then(() => trim(ASSETS, 250));
        }
        return res;
    }).catch(() => null);
    if (hit) {
        e.waitUntil(net);
        return hit;
    }
    return (await net) || new Response('', { status: 504, statusText: 'Offline' });
}

function esc(s) {
    return String(s ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
}

function offlinePage(extra = '') {
    const html = `<!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>অফলাইন — ${esc(CFG.name)}</title><style>body{font-family:system-ui,'Hind Siliguri',sans-serif;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0;background:#f8fafc;color:#111827;text-align:center;padding:24px}
.box{max-width:380px}.i{font-size:56px}.b{display:inline-block;margin-top:14px;padding:10px 18px;border-radius:10px;background:${esc(CFG.color || '#111827')};color:#fff;text-decoration:none;border:0;font-size:15px;cursor:pointer}</style></head>
<body><div class="box"><div class="i">📶</div><h2>ইন্টারনেট সংযোগ নেই</h2><p>${esc(CFG.name)} — নেট ফিরে এলে পাতাটি আবার চেষ্টা করুন। আগে দেখা পাতাগুলো অফলাইনেও খোলা যায়।</p>
<button class="b" onclick="location.reload()">আবার চেষ্টা করুন</button>${extra}</div></body></html>`;
    return new Response(html, { status: 200, headers: { 'Content-Type': 'text/html; charset=utf-8' } });
}
@endverbatim
